import type { ComponentType, SVGProps } from "react";

/**
 * The Clarity icon set: the app's own icons, drawn once in the brand greens.
 *
 * Traced from the approved 160px PNG masters into two-tone paths on a 24-unit
 * grid, so they sit where the stock line icons sat and stay crisp at any size.
 * The dark part is currentColor, so an icon still follows the text it sits
 * beside (dark mode, a white-on-black button, a muted row). The green accent is
 * --c-icon-accent, fixed in both schemes because the green is the brand.
 *
 * Utility glyphs the set has no answer for (close, chevrons, tick, plus, trash)
 * stay on lucide-react. Anything the set does cover comes from here.
 */

export type IconComponent = ComponentType<{ size?: number | string; className?: string }>;

type ClarityIconProps = Omit<SVGProps<SVGSVGElement>, "children"> & { size?: number | string };

function clarityIcon(name: string, dark: string, accent: string) {
  function Icon({ size = 24, className, ...rest }: ClarityIconProps) {
    return (
      <svg
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 24 24"
        width={size}
        height={size}
        aria-hidden="true"
        focusable="false"
        className={className ? `clarity-icon ${className}` : "clarity-icon"}
        {...rest}
      >
        <path fill="currentColor" d={dark} />
        {accent ? <path className="clarity-icon-accent" d={accent} /> : null}
      </svg>
    );
  }
  Icon.displayName = name;
  return Icon;
}

